function updateBubbles(dt){for(let i=bubbles.length-1;i>=0;i--){const b=bubbles[i];if(mode==='play')b.ttl-=dt;if(b.ttl<=0){b.el.remove();bubbles.splice(i,1);continue;}const v=new THREE.Vector3();b.npc.model.getWorldPosition(v);v.y+=2.7;v.project(world.camera);b.el.style.display=v.z<1&&Math.abs(v.x)<1.1&&Math.abs(v.y)<1.1?'block':'none';b.el.style.left=(v.x*.5+.5)*innerWidth+'px';b.el.style.top=(-v.y*.5+.5)*innerHeight+'px';}}
function loop(t){requestAnimationFrame(loop);const dt=Math.min(.045,(t-last)/1000||.016);last=t;if(!world||!sim)return;if(mode==='play')worldStep(dt);cameraStep(dt,t/1000);for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.ttl-=dt;p.v.y-=6*dt;p.m.position.addScaledVector(p.v,dt);p.m.rotation.x+=dt*3;p.m.rotation.z+=dt*2;if(p.ttl<=0){p.m.removeFromParent();particles.splice(i,1);}}world.flags.forEach((o,i)=>o.rotation.y=Math.sin(t*.002+i)*.2);updateBubbles(dt);if(toastTime>0){toastTime-=dt;if(toastTime<=0)$('#toast').style.opacity=0;}if(t-lastUI>100){updateUI();lastUI=t;}world.renderer.render(world.scene,world.camera);$('#vignette').style.background=photoTime>0?'#fff8':sim.pursuit?'radial-gradient(ellipse at center,transparent 45%,#9d382b30)':'radial-gradient(ellipse at center,transparent 40%,#0b211929)';}
